  processor: ["cards", "wait", "compiler"], planner: ["cards", "contour", "language"],
  builder: ["cards", "language"],
  primer: ["cards", "git", "store", "language"],
  scout: ["cards", "processor", "wait", "primer"],
  reviewer: ["cards", "contour", "primer", "scout", "git"],
